import { recordScan } from '@projexlight/hdk-scanner';
await recordScan({
  tenant_id, persona_id: staff.id, device_uuid,
  kind: 'qr', value: ticket_qr_payload,
});

import { recordScan } from '@projexlight/hdk-scanner';
const { scan_id } = await recordScan({
  tenant_id, kind: 'barcode-code128',
  value: 'EVID-2026-05-26-001', device_uuid,
});

const caps = await fetch('/api/hdk/scanner/capabilities').then(r => r.json());
if (caps.nfc) enableTapToConfirm();
if (caps.hardware_laser) enableLaserMode();
